use vstd::prelude::*;

verus! {

    // copy: given a vector of i8, returns a new vector with the same contents
    fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
        ensures
            // the result has the same length as the input
            result.len() == arr.len(),
        ensures
            // and for every index in range, the elements agree
            forall |i: usize| i < arr.len() ==> result.index(i) == arr.index(i)
    {
        let mut result: Vec<i8> = Vec::new();
        let mut idx: usize = 0;
        // Build up result by pushing elements one by one.
        while idx < arr.len()
            invariant
                // we've processed up to idx
                idx <= arr.len(),
                // result so far has length idx
                result.len() == idx,
                // and matches arr on all processed positions
                forall |i: usize| i < idx ==> result.index(i) == arr.index(i),
            decreases arr.len() - idx
        {
            // copy the element at idx
            let elt: i8 = arr.index(idx);
            result.push(elt);
            idx = idx + 1;
        }
        result
    }

}

